using RealmForge.Domain.Entities;
using RealmForge.Shared.Characters;
using RealmForge.Shared.Enums;
using static RealmForge.Infrastructure.Persistence.Seeding.MagicItemSeeder;

namespace RealmForge.Infrastructure.Persistence.Seeding.MagicItemsData;

///	<summary>
///	Deck of Many Things (2014 ruleset). SRD 5.1 text (CC BY 4.0) in English and in the official Italian SRD 5.1 (CC BY 4.0).
///	</summary>
public static class DeckOfManyThings2014Seeder
{
	public static IEnumerable<MagicItem> Build()
	{
		yield return Item("deck-of-many-things", null, 0, MagicItemType.WondrousItem, ItemRarity.Legendary, false, ContentSource.Srd51,
			null,
			("Mazzo delle meraviglie", "Oggetto meraviglioso, leggendario",
			"Questo mazzo in genere si trova in una scatola o in un sacchetto ed è composto da una serie di carte di avorio o di vellum. La maggior parte di questi mazzi (il 75 percento) è composta soltanto da 13 carte, mentre il resto ne ha 22.\n\nPrima di pescare una carta, il personaggio deve dichiarare quante carte ha intenzione di pescare complessivamente e poi pescarle in maniera casuale (è possibile usare un normale mazzo di carte opportunamente modificato per simulare quest'oggetto). Le eventuali carte pescate in eccesso oltre il numero dichiarato non hanno alcun effetto. Altrimenti, non appena il personaggio pesca una carta dal mazzo, la sua magia ha effetto. Il personaggio deve pescare ogni carta entro 1 ora dall'ultima carta pescata. Se non riesce a pescare il numero di carte dichiarato, le carte restanti volano via dal mazzo da sole e hanno effetto simultaneamente.\n\nUna volta pescate dal mazzo, le carte svaniscono. A eccezione della Matta e del Giullare, le altre carte ricompaiono nel mazzo, quindi è possibile pescare la stessa carta due volte.\n\n| Carta da gioco Carta |\n|---|\n| Asso di quadri Visir* |\n| Re di quadri Sole |\n| Regina di quadri Luna |\n| Jack di quadri Stella |\n| Due di quadri Cometa* |\n| Asso di cuori Destino* |\n| Re di cuori Trono |\n| Regina di cuori Chiave |\n| Jack di cuori Cavaliere |\n| Due di cuori Gemma* |\n| Asso di fiori Artigli* |\n| Re di fiori Il vuoto |\n| Regina di fiori Fiamme |\n| Jack di fiori Teschio |\n| Due di fiori Idiota* |\n| Asso di spade Prigione* |\n| Re di picche Rovina |\n| Regina di picche Eurialo |\n| Jack di picche Ladro |\n| Due di picche Bilancia* |\n| Jolly (con marca) Matta* |\n| Jolly (senza marca) Giullare |\n\n* Presente solo in mazzi con 22 carte\n\n***Artigli.*** Tutti gli oggetti magici indossati o trasportati dal personaggio si disintegrano. I manufatti posseduti dal personaggio non si disintegrano ma svaniscono.\n\n***Bilancia.*** La mente del personaggio è sottoposta a una sofferta alterazione che modifica il suo allineamento. Un legale diventa caotico, un buono diventa malvagio e viceversa. Se il personaggio è neutrale o senza allineamento, questa carta non ha alcun effetto su di lui.\n\n***Cavaliere.*** Il personaggio ottiene i servigi di un guerriero di 4° livello che appare in un spazio a sua scelta entro 9 metri da lui. Il guerriero è della stessa razza del personaggio e lo serve fedelmente fino alla morte, convinto che sia stato il destino a condurlo da lui. Il personaggio ha il controllo del guerriero.\n\n***Chiave.*** Nella mano del personaggio appare un'arma magica rara, molto rara o leggendaria in cui è competente. L'arma viene scelta dal GM.\n\n***Cometa.*** Se il personaggio sconfigge da solo il successivo mostro o gruppo di mostri ostili che incontra, ottiene abbastanza punti esperienza da aumentare di livello. Altrimenti, la carta non ha alcun effetto.\n\n***Destino.*** La trama della realtà si disfa e si ricompone, permettendo al personaggio di evitare o annullare un evento come se non fosse mai avvenuto. Il personaggio può usare la magia della carta non appena la pesca o in qualsiasi altro momento prima della sua morte.\n\n***Eurialo.*** Il volto di medusa raffigurato sulla carta maledice il personaggio. Finché è maledetto in questo modo, il personaggio subisce una penalità di –2 ai tiri salvezza. Solo un dio o la magia della carta Destino può porre fine a questa maledizione.\n\n***Fiamme.*** Il personaggio si inimica un potente diavolo, che desidera condurlo alla rovina e avvelenerà la sua vita in ogni modo, assaporando ogni istante della sua sofferenza prima di tentare di distruggerlo. Questa ostilità dura finché uno dei due non muore.\n\n***Gemma.*** Ai piedi del personaggio appaiono venticinque gemme del valore di 2.000 mo ognuna o cinquanta gemme del valore di 1.000 mo ognuna.\n\n***Giullare.*** Il personaggio ottiene 10.000 PE oppure può pescare due carte aggiuntive oltre al numero dichiarato di carte da pescare.\n\n***Idiota.*** Il punteggio di Intelligenza del personaggio si riduce permanentemente di 1d4 + 1 (fino a un punteggio minimo di 1). Il personaggio può pescare un'altra carta oltre al numero dichiarato.\n\n***Ladro.*** Un personaggio non giocante a scelta del GM diventa ostile nei confronti del personaggio. L'identità del nuovo nemico è ignota al personaggio finché lo stesso PNG o qualcun altro non la rivela. Solo un incantesimo *desiderio* o un intervento divino possono annullare l'ostilità del PNG.\n\n***Luna.*** Il personaggio ottiene la capacità di lanciare l'incantesimo *desiderio* per 1d3 volte.\n\n***Matta.*** Il personaggio perde 10.000 PE, scarta questa carta e ne pesca un'altra; la pesca di entrambe queste carte conta solo come una ai fini del numero dichiarato di carte da pescare. Se la perdita di questi PE provocasse la perdita di un livello, il personaggio perde invece solo l'ammontare di PE che gli consente di rimanere al livello attuale.\n\n***Prigione.*** Il personaggio scompare e resta intrappolato in stato di animazione sospesa all'interno di una sfera extradimensionale. Tutto ciò che indossava e trasportava resta nello spazio che occupava al momento della sua scomparsa. Il personaggio resta imprigionato finché non viene trovato e rimosso dalla sfera. Non è possibile localizzare il personaggio attraverso alcuna magia di divinazione, ma un incantesimo *desiderio* può rivelare la posizione della prigione. Il personaggio non può pescare altre carte.\n\n***Rovina.*** Ogni forma di ricchezza trasportata o posseduta dal personaggio, a eccezione degli oggetti magici, va perduta. Le proprietà trasportabili svaniscono. Le attività commerciali, gli edifici e le terre possedute vanno perdute nel modo che richiede l'alterazione della realtà più limitata. Tutti i documenti che potrebbero dimostrare il possesso delle proprietà perdute a causa della carta svaniscono a loro volta.\n\n***Sole.*** Il personaggio guadagna 50.000 PE e un oggetto meraviglioso (determinato a caso dal GM) gli appare in mano.\n\n***Stella.*** Un punteggio di caratteristica del personaggio aumenta di 2. Il nuovo punteggio può essere superiore a 20, ma non a 24.\n\n***Teschio.*** Il personaggio evoca un avatar della morte: uno spettrale scheletro umanoide avvolto in una veste nera stracciata e armato di una falce spettrale. Lo scheletro appare in uno spazio a scelta dal GM entro 3 metri dal personaggio e lo attacca, intimando agli altri presenti di non immischiarsi. L'avatar combatte finché non uccide il personaggio o non scende a 0 punti ferita, nel qual caso scompare. Se qualcuno tenta di aiutare il personaggio, evoca a sua volta un altro avatar della morte. Una creatura uccisa da un avatar della morte non può essere riportata in vita.\n\n**Avatar della morte**\n\n*Non morto Medio, neutrale malvagio*\n\n**Classe Armatura** 20\n**Punti Ferita** metà dei punti ferita massimi del suo evocatore\n**Velocità** 18 m, volare 18 m (fluttuare)\n\n| FOR | DES | COS | INT | SAG | CAR |\n|---|---|---|---|---|---|\n| 16 (+3) | 16 (+3) | 16 (+3) | 16 (+3) | 16 (+3) | 16 (+3) |\n\n**Immunità ai Danni** necrotici, veleno\n**Immunità alle Condizioni** affascinato, avvelenato, paralizzato, pietrificato, privo di sensi, spaventato\n**Sensi** Percezione passiva 13, scurovisione 18 m, vista pura 18 m\n**Linguaggi** tutti i linguaggi conosciuti dal suo evocatore\n**Sfida** — (0 PE)\n\n***Immunità allo scacciare.*** L'avatar è immune agli effetti che scacciano i non morti.\n\n***Movimento incorporeo.*** L'avatar può muoversi attraverso altre creature e oggetti come se fossero terreno difficile. Subisce 5 (1d10) danni da forza se termina il proprio turno all'interno di un oggetto.\n\n**Azioni**\n\n***Falce del Mietitore.*** L'avatar sferra un fendente con la falce spettrale attraverso una creatura situata entro 1,5 metri da esso, infliggendo 7 (1d8+3) danni taglienti più 4 (1d8) danni necrotici.\n\n***Trono.*** Il personaggio ottiene competenza nell'abilità Persuasione e il suo bonus di competenza alle prove di Persuasione raddoppia. Inoltre, il personaggio diventa il legittimo proprietario di un piccolo castello situato da qualche parte nel mondo. Tuttavia, il castello è infestato da mostri e il personaggio dovrà scacciarli prima di poterlo rivendicare come suo.\n\n***Visir.*** In qualunque momento desideri, entro un anno da quando pesca questa carta, il personaggio può porre una domanda mentre medita e ottenere mentalmente una risposta veritiera. Oltre alle informazioni, la risposta lo aiuta a risolvere un problema intricato o un dilemma di altro tipo. In altre parole, oltre alla conoscenza ottiene anche la saggezza necessaria ad applicarla.\n\n***Vuoto.*** Questa carta nera è foriera di sventura. L'anima del personaggio viene strappata dal corpo e rinchiusa in un oggetto situato in un luogo scelto dal GM. Tale luogo è protetto da uno o più potenti guardiani. Fintantoché l'anima del personaggio è intrappolata in questo modo, il suo corpo è incapacitato. Un incantesimo *desiderio* non può riportare l'anima del personaggio nel corpo, ma può rivelare il luogo in cui si trova l'oggetto che la custodisce. Il personaggio non può pescare altre carte."),
			("Deck of Many Things", "Wondrous item, legendary",
			"Usually found in a box or pouch, this deck contains a number of cards made of ivory or vellum. Most (75 percent) of these decks have only thirteen cards, but the rest have twenty-two.\n\nBefore you draw a card, you must declare how many cards you intend to draw and then draw them randomly (you can use an altered deck of playing cards to simulate the deck). Any cards drawn in excess of this number have no effect. Otherwise, as soon as you draw a card from the deck, its magic takes effect. You must draw each card no more than 1 hour after the previous draw. If you fail to draw the chosen number, the remaining number of cards fly from the deck on their own and take effect all at once.\n\nOnce a card is drawn, it fades from existence. Unless the card is the Fool or the Jester, the card reappears in the deck, making it possible to draw the same card twice.\n\n| Playing Card | Card |\n|---|---|\n| Ace of diamonds | Vizier* |\n| King of diamonds | Sun |\n| Queen of diamonds | Moon |\n| Jack of diamonds | Star |\n| Two of diamonds | Comet* |\n| Ace of hearts | The Fates* |\n| King of hearts | Throne |\n| Queen of hearts | Key |\n| Jack of hearts | Knight |\n| Two of hearts | Gem* |\n| Ace of clubs | Talons* |\n| King of clubs | The Void |\n| Queen of clubs | Flames |\n| Jack of clubs | Skull |\n| Two of clubs | Idiot* |\n| Ace of spades | Donjon* |\n| King of spades | Ruin |\n| Queen of spades | Euryale |\n| Jack of spades | Rogue |\n| Two of spades | Balance* |\n| Joker (with TM) | Fool* |\n| Joker (without TM) | Jester |\n\n* Found only in a deck with twenty-two cards\n\n***Balance.*** Your mind suffers a wrenching alteration, causing your alignment to change. Lawful becomes chaotic, good becomes evil, and vice versa. If you are true neutral or unaligned, this card has no effect on you.\n\n***Comet.*** If you single-handedly defeat the next hostile monster or group of monsters you encounter, you gain experience points enough to gain one level. Otherwise, this card has no effect.\n\n***Donjon.*** You disappear and become entombed in a state of suspended animation in an extradimensional sphere. Everything you were wearing and carrying stays behind in the space you occupied when you disappeared. You remain imprisoned until you are found and removed from the sphere. You can't be located by any divination magic, but a wish spell can reveal the location of your prison. You draw no more cards.\n\n***Euryale.*** The card's medusa-like visage curses you. You take a -2 penalty on saving throws while cursed in this way. Only a god or the magic of The Fates card can end this curse.\n\n**The Fates.** Reality's fabric unravels and spins anew, allowing you to avoid or erase one event as if it never happened. You can use the card's magic as soon as you draw the card or at any other time before you die.\n\n***Flames.*** A powerful devil becomes your enemy. The devil seeks your ruin and plagues your life, savoring your suffering before attempting to slay you. This enmity lasts until either you or the devil dies.\n\n***Fool.*** You lose 10,000 XP, discard this card, and draw from the deck again, counting both draws as one of your declared draws. If losing that much XP would cause you to lose a level, you instead lose an amount that leaves you with just enough XP to keep your level.\n\n***Gem.*** Twenty-five pieces of jewelry worth 2,000 gp each or fifty gems worth 1,000 gp each appear at your feet.\n\n***Idiot.*** Permanently reduce your Intelligence by 1d4 + 1 (to a minimum score of 1). You can draw one additional card beyond your declared draws.\n\n***Jester.*** You gain 10,000 XP, or you can draw two additional cards beyond your declared draws.\n\n***Key.*** A rare or rarer magic weapon with which you are proficient appears in your hands. The GM chooses the weapon.\n\n***Knight.*** You gain the service of a 4th-level fighter who appears in a space you choose within 30 feet of you. The fighter is of the same race as you and serves you loyally until death, believing the fates have drawn him or her to you. You control this character.\n\n***Moon.*** You are granted the ability to cast the wish spell 1d3 times.\n\n***Rogue.*** A nonplayer character of the GM's choice becomes hostile toward you. The identity of your new enemy isn't known until the NPC or someone else reveals it. Nothing less than a wish spell or divine intervention can end the NPC's hostility toward you.\n\n***Ruin.*** All forms of wealth that you carry or own, other than magic items, are lost to you. Portable property vanishes. Businesses, buildings, and land you own are lost in a way that alters reality the least. Any documentation that proves you should own something lost to this card also disappears.\n\n***Skull.*** You summon an avatar of death-a ghostly humanoid skeleton clad in a tattered black robe and carrying a spectral scythe. It appears in a space of the GM's choice within 10 feet of you and attacks you, warning all others that you must win the battle alone. The avatar fights until you die or it drops to 0 hit points, whereupon it disappears. If anyone tries to help you, the helper summons its own avatar of death. A creature slain by an avatar of death can't be restored to life.\n\n**Avatar of Death**\n\n*Medium undead, neutral evil*\n\n**Armor Class** 20\n**Hit Points** half the hit point maximum of its summoner\n**Speed** 60 ft., fly 60 ft. (hover)\n\n| STR | DEX | CON | INT | WIS | CHA |\n|---|---|---|---|---|---|\n| 16 (+3) | 16 (+3) | 16 (+3) | 16 (+3) | 16 (+3) | 16 (+3) |\n\n**Damage Immunities** necrotic, poison\n**Condition Immunities** charmed, frightened, paralyzed, petrified, poisoned, unconscious\n**Senses** darkvision 60 ft., truesight 60 ft., passive Perception 13\n**Languages** all languages known to its summoner\n**Challenge** — (0 XP)\n\n***Incorporeal Movement.*** The avatar can move through other creatures and objects as if they were difficult terrain. It takes 5 (1d10) force damage if it ends its turn inside an object.\n\n***Turning Immunity.*** The avatar is immune to features that turn undead.\n\n**Actions**\n\n***Reaping Scythe.*** The avatar sweeps its spectral scythe through a creature within 5 feet of it, dealing 7 (1d8 + 3) slashing damage plus 4 (1d8) necrotic damage.", null));
	}
}
